// Block (composition) — a field whose value is a list of rows the author adds and removes: option
// names with their prices, a set of phone numbers, tiers of a discount. A dashboard's or a POS's option
// editor draws it: name + price + trash per row, 「+ 추가하기」 below, the first row locked.
//
// Not SequenceEditor: there the order is the value and a row holds one string; here a row is a group
// of fields, order is not edited in place (a product edits it on its own 「순서편집」 screen), and a row
// may be locked. The row's fields are the caller's (`renderRow`), the way DataTable takes a cell
// renderer; this Block owns the field-array behaviour: add, remove, which rows may be removed, and
// where focus lands after each.
//
// Focus never falls to the page. Adding a row moves focus into its first field, so the next keystroke
// types into it; removing a row moves focus into the row that took its place, or the last row, or the
// add Button when no row is left.
//
// The caller names each field, with the row in the name ("옵션 이름 2"): the visible label names the
// column, and a placeholder is not a name. `removeLabel` names each remove control the same way.
//
// ponytail: no maximum row count; pass `isAddDisabled` when a cap is reached. Add one when a device
// needs it announced.
import { useEffect, useId, useRef, type ReactNode, type Ref } from "react";
import { Plus, Trash } from "../components/icons";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./RepeaterField.css";

export interface RepeaterRow {
  /** Stable across edits to the row's fields, so typing in a row never remounts it. */
  id: string;
}

export interface RepeaterFieldProps<T extends RepeaterRow> {
  /**
   * Size of the label, the remove controls and the add Button. Match the fields `renderRow` draws.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /** The visible name of the column of rows, e.g. "옵션 이름". Also the group's name. */
  label: string;
  /** The rows, in order. Controlled. */
  rows: T[];
  /** The row's fields. They share the row's width equally. */
  renderRow: (row: T, index: number) => ReactNode;
  /** Appends a row: the caller mints its id. */
  onAdd: () => void;
  /** The add Button's text, e.g. "추가하기". */
  addLabel: string;
  /** When true the add Button shows but cannot be pressed. */
  isAddDisabled?: boolean;
  /** Removes a row. */
  onRemove: (row: T, index: number) => void;
  /** Accessible name of a row's remove control, e.g. "고소 삭제". */
  removeLabel: (row: T, index: number) => string;
  /**
   * Whether a row may be removed. The control shows on every row, disabled where this is false.
   *
   * @default keeps the last row: removable while more than one remains
   */
  canRemove?: (row: T, index: number) => boolean;
  /** Additional class (optional). sd-repeater-field is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLElement>;
}

function firstFocusable(root: Element): HTMLElement | null {
  const all = root.querySelectorAll<HTMLElement>("input, textarea, select, button, [tabindex]");
  for (const el of all) {
    const hidden = el instanceof HTMLInputElement && el.type === "hidden";
    if (!hidden && el.tabIndex >= 0 && !el.matches(":disabled") && el.getClientRects().length > 0) return el;
  }
  return null;
}

export function RepeaterField<T extends RepeaterRow>({
  size = "medium",
  label,
  rows,
  renderRow,
  onAdd,
  addLabel,
  isAddDisabled,
  onRemove,
  removeLabel,
  canRemove = () => rows.length > 1,
  className,
  ref,
}: RepeaterFieldProps<T>) {
  const labelId = useId();
  const listRef = useRef<HTMLDivElement>(null);
  const addRef = useRef<HTMLButtonElement>(null);
  // What to focus once the caller's rows reflect a request, keyed on row identity rather than on time
  // or count: a removed row's focus moves when that id is gone, an added row's when an id appears that
  // was not there. A request the caller declines simply waits; the next request replaces it. A caller
  // that confirms asynchronously (a dialog) still gets focus moved when the rows finally change.
  const pending = useRef<{ kind: "remove"; id: string; at: number } | { kind: "add"; known: Set<string> } | null>(null);

  useEffect(() => {
    const p = pending.current;
    if (p === null) return;
    let at: number;
    if (p.kind === "remove") {
      if (rows.some((r) => r.id === p.id)) return;
      at = Math.min(p.at, rows.length - 1);
    } else {
      // An add is answered by a longer list with an id that was not there; a same-length replacement
      // is not an add, so it never takes focus.
      if (rows.length <= p.known.size) return;
      at = rows.findIndex((r) => !p.known.has(r.id));
      if (at < 0) return;
    }
    pending.current = null;
    const row = at >= 0 ? listRef.current?.children[at] : undefined;
    // The first control a person can reach: skips hidden and disabled inputs, such as the hidden
    // input React Aria keeps inside a DateField. With no row left, the add Button.
    const target = row ? firstFocusable(row) : null;
    (target ?? addRef.current)?.focus();
  }, [rows]);

  return (
    <Stack
      ref={ref}
      gap="small"
      role="group"
      aria-labelledby={labelId}
      className={className ? `sd-repeater-field ${className}` : "sd-repeater-field"}
    >
      {/* The label heads a column of field boxes that share its start edge, so it takes the text
          inset (component-contract.md §6 rule 8). */}
      <>
        <span id={labelId} className={`sd-repeater-field__label sd-type-label-${size}`}>
          {label}
        </span>
      </>
      <Stack ref={listRef} gap="x-small">
        {rows.map((row, i) => (
          <Stack key={row.id} direction="row" gap="small" align="start">
            <div className="sd-repeater-field__fields">{renderRow(row, i)}</div>
            <Button
              isIconOnly
              variant="secondary"
              size={size}
              aria-label={removeLabel(row, i)}
              isDisabled={!canRemove(row, i)}
              onPress={() => {
                pending.current = { kind: "remove", id: row.id, at: i };
                onRemove(row, i);
              }}
            >
              <Trash aria-hidden size="1em" />
            </Button>
          </Stack>
        ))}
      </Stack>
      {/* spacing: attachment — the add Button extends the rows above it */}
      <Button
        ref={addRef}
        variant="secondary"
        size={size}
        isDisabled={isAddDisabled}
        onPress={() => {
          pending.current = { kind: "add", known: new Set(rows.map((r) => r.id)) };
          onAdd();
        }}
      >
        <Plus aria-hidden size="1em" />
        {addLabel}
      </Button>
    </Stack>
  );
}

/* Layout only (block-contract.md §3, §5): Stack places the label, the rows and the add Button. A
   row's fields take equal columns of what the remove control leaves, as an option editor does
   (name | price). The label sits one text inset in from the fields' box line, through `Indent`
   (component-contract.md §6 rule 8). */
.sd-repeater-field__fields {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  gap: var(--sd-space-x-small);
}
